// Backend & APIs (category 'backend') — 144 linkless Question Bank rows for
// full-stack "product engineer" loops. answer_hints = the 4–6 key points the
// scorecard grades against ("·" separates them). sort_order puts the
// must-haves first, easy before medium before hard within each group.
//
// Pitched at a frontend-heavy full-stack engineer (v4.10.2): the questions
// that went deep into infrastructure were rewritten as plain, practical ones.
// `was` = the old title, so the seed updates that same row (keeping its
// progress) instead of inserting a new one.

const q = (title, difficulty, topics, answer_hints, was) => ({ title, difficulty, topics, answer_hints, ...(was ? { was } : {}) })

