// Must-haves first, then easy → medium → hard, otherwise the order above.
const must = r => r.topics.includes('Must-have') ? 0 : 1
const LEVEL = { easy: 0, medium: 1, hard: 2 }
export default [...ROWS].sort((a, b) => must(a) - must(b) || LEVEL[a.difficulty] - LEVEL[b.difficulty]).map((r, i) => ({ ...r, sort_order: i + 1 }))
